    "seedSQL": "CREATE TABLE employees (id INTEGER PRIMARY KEY, name TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1, 'Alice', 90000);\nINSERT INTO employees VALUES (2, 'Bob', 70000);\nINSERT INTO employees VALUES (3, 'Charlie', 95000);\nINSERT INTO employees VALUES (4, 'Diana', 85000);",
    "expectedQuery": "WITH avg_salary AS (SELECT AVG(salary) as avg FROM employees) SELECT * FROM employees, avg_salary WHERE employees.salary > avg_salary.avg;",
    "solutionSQL": "WITH avg_salary AS (SELECT AVG(salary) as avg FROM employees) SELECT * FROM employees, avg_salary WHERE employees.salary > avg_salary.avg;",
